((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":2008,"id":"2008-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_2008_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_2008_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Буквы в алфавитном порядке","question":"Какое наименьшее количество букв нужно вычеркнуть из фразы УРА КЕНГУРУ, чтобы оставшиеся буквы были различны и шли слева направо в алфавитном порядке?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Для каждой буквы найдём, сколько возрастающих букв можно оставить, если закончить на ней. Берём единицу плюс наибольшую уже найденную длину для предшествующей буквы из алфавита."},{"title":"Решение","text":"Для букв У, Р, А, К, Е, Н, Г, У, Р, У получаем длины 1, 1, 1, 2, 2, 3, 2, 4, 4, 5. Например, можно оставить А, Е, Н, Р, У."},{"title":"Ответ","text":"Максимум остаются пять букв из десяти. Значит, вычёркиваем пять."}]},{"number":2,"title":"Узлы на верёвках","question":"Какие из следующих верёвочек завяжутся в узел, если потянуть их за концы?","options":[{"text":"II и III"},{"text":"I и III"},{"text":"только I"},{"text":"только II"},{"text":"только III"}],"condition":{"src":"assets/grades-7-8/2008/task-02.svg","width":621,"height":168,"alt":"Три переплетённые верёвочки I, II и III"},"answer":4,"points":3,"review":[{"title":"Решение","text":"Проследим каждую верёвку, различая проходы сверху и снизу. В I свободный изгиб вытягивается через петлю, а в II петлю можно перевернуть и убрать перекрещивания."},{"title":"Ответ","text":"У III конец продет через петли так, что при натяжении получается простой узел. Это можно проверить шнурком, повторив, какая ветвь в каждом пересечении лежит сверху."}]},{"number":3,"title":"Цифры произведения степеней","question":"Чему равна сумма цифр числа 2²⁰⁰⁸ · 5²⁰¹¹?","options":[{"text":"1"},{"text":"3"},{"text":"7"},{"text":"8"},{"text":"13"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Составим из 2008 двоек и 2008 пятёрок пары. Каждая пара даёт 10, а остаются три пятёрки."},{"title":"Ответ","text":"Число равно 125 · 10²⁰⁰⁸. Его ненулевые цифры 1, 2 и 5 дают сумму 8."}]},{"number":4,"title":"Периметр восьмиугольника","question":"Каждый из треугольников и квадрат имеют периметр 16 см. Чему равен периметр нарисованного восьмиугольника?","options":[{"text":"40 см"},{"text":"45 см"},{"text":"48 см"},{"text":"56 см"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-7-8/2008/task-04.svg","width":276,"height":267,"alt":"Четыре треугольника приложены к сторонам квадрата"},"answer":2,"points":3,"review":[{"title":"Решение","text":"Сторона квадрата равна 16 : 4 = 4 см. У каждого треугольника одна сторона совпадает со стороной квадрата, так что его две внешние стороны имеют общую длину 16 − 4 = 12 см."},{"title":"Ответ","text":"Граница восьмиугольника составлена из таких пар. Периметр равен 4 · 12 = 48 см."}]},{"number":5,"title":"Слова от одного до ста","question":"Жан-Кристоф продолжает изучать русский язык. Он считает вслух по-русски от одного до ста. Сколько слов он при этом произнесёт?","options":[{"text":"100"},{"text":"172"},{"text":"181"},{"text":"190"},{"text":"200"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Одним словом произносятся числа от 1 до 19, восемь круглых десятков от 20 до 90 и само число 100. Это 19 + 8 + 1 = 28 чисел."},{"title":"Ответ","text":"Оставшиеся 72 числа произносятся двумя словами. Получаем 28 + 72 · 2 = 172 слова."}]},{"number":6,"title":"Квадраты из точек","question":"Какое наибольшее число квадратов можно нарисовать, соединяя точки на рисунке отрезками?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-7-8/2008/task-06.svg","width":150,"height":147,"alt":"Сетка три на три с восемью точками, без нижнего левого угла"},"answer":2,"points":3,"review":[{"title":"Решение","text":"В полной сетке из девяти точек можно построить четыре единичных квадрата, один большой квадрат со сторонами вдоль сетки и один наклонный квадрат через середины сторон большого."},{"title":"Ответ","text":"В рисунке не хватает нижней левой точки. Без неё исчезают нижний левый единичный и большой квадрат. Остаётся 4 квадрата."}]},{"number":7,"title":"Задачи из набора жюри","question":"Начиная с первого сентября, жюри конкурса «Кенгуру» каждый день с 9 до 14 часов придумывает 6 новых задач, а после обеда, с 15 до 20 часов, отвергает 4 из них. В какой день жюри впервые получит набор из 30 задач?","options":[{"text":"16 сентября"},{"text":"15 сентября"},{"text":"14 сентября"},{"text":"13 сентября"},{"text":"12 сентября"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"К вечеру каждого дня число задач увеличивается на 6 − 4 = 2."},{"title":"Ответ","text":"Вечером 12 сентября останется 24 задачи. Утром 13 сентября к ним добавятся шесть и получится 30. Утром 12 сентября их было только 22 + 6 = 28."}]},{"number":8,"title":"Углы трёх прямых","question":"Три прямые пересекаются в одной точке. Градусные меры некоторых углов указаны на рисунке. Чему равен закрашенный угол?","options":[{"text":"52°"},{"text":"53°"},{"text":"54°"},{"text":"55°"},{"text":"56°"}],"condition":{"src":"assets/grades-7-8/2008/task-08.svg","width":246,"height":207,"alt":"Три пересекающиеся прямые, углы 108° и 124° и закрашенный сектор"},"answer":0,"points":3,"review":[{"title":"Решение","text":"Угол между верхним вертикальным лучом и левым верхним наклонным равен 180° − 124° = 56°, поскольку эти наклонные лучи противоположны."},{"title":"Ответ","text":"Угол 108° состоит из угла 56° и закрашенного. Вычитаем 108° − 56° = 52°."}]},{"number":9,"title":"Надпись в зеркале","question":"Встречая Новый год, Вася надел футболку с надписью 2008 на груди и встал на руки (вверх ногами) перед зеркалом. Что увидел в зеркале его друг Коля, который стоял (на ногах) рядом с Васей?","options":[{"text":"2008","image":"assets/grades-7-8/2008/task-09-answer-1.svg","description":"Надпись 2008"},{"text":"2005","image":"assets/grades-7-8/2008/task-09-answer-2.svg","description":"Надпись 2005"},{"text":"8002","image":"assets/grades-7-8/2008/task-09-answer-3.svg","description":"Надпись 8002"},{"text":"8005","image":"assets/grades-7-8/2008/task-09-answer-4.svg","description":"Надпись 8005"},{"text":"5008","image":"assets/grades-7-8/2008/task-09-answer-5.svg","description":"Надпись 5008"}],"condition":{"src":"assets/grades-7-8/2008/task-09.svg","width":147,"height":66,"alt":"Исходная надпись 2008, начертанная угловатыми сегментами"},"answer":4,"points":3,"review":[{"title":"Решение","text":"Когда Вася встаёт на руки, надпись поворачивается на 180° и её порядок справа налево меняется. Зеркало снова меняет левую и правую стороны."},{"title":"Ответ","text":"Вместе эти два действия дают отражение относительно горизонтальной линии. У цифр 0 и 8 рисунок сохраняется, а 2 превращается в 5. Коля увидит 5008."}]},{"number":10,"title":"Квадрат суммы","question":"Квадрат суммы чисел a и b равен сумме квадратов этих чисел. Какое из утверждений обязательно верно?","options":[{"text":"Сумма чисел a и b равна 0."},{"text":"Оба числа a и b равны нулю."},{"text":"Это верно для любых a и b."},{"text":"Это невозможно ни для каких a и b."},{"text":"Хотя бы одно из чисел a и b равно нулю."}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Раскроем скобки: (a + b)² = a² + 2ab + b²."},{"title":"Ответ","text":"После сокращения квадратов остаётся 2ab = 0. Значит, хотя бы одно из чисел равно нулю."}]},{"number":11,"title":"Шифр из квадратов цифр","question":"Вася шифрует трёхзначные числа: вместо каждой цифры он пишет последнюю цифру её квадрата (например, вместо 7 он пишет 9, а вместо 2 пишет 4). Из скольких чисел после шифрования получится число 465?","options":[{"text":"1"},{"text":"2"},{"text":"4"},{"text":"5"},{"text":"8"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Последняя цифра 4 получается у квадратов 2 и 8, цифра 6 — у квадратов 4 и 6, цифра 5 — только у квадрата 5."},{"title":"Ответ","text":"Выбираем цифры независимо. Получится 2 · 2 · 1 = 4 исходных числа."}]},{"number":12,"title":"Дни рождения друзей","question":"Семиклассники Саша и Паша дружат с первого класса. Они заметили, что каждый год их дни рождения приходятся на один и тот же день недели. Саша родился в апреле. Тогда день рождения Паши не может быть","options":[{"text":"в мае"},{"text":"в июне"},{"text":"в августе"},{"text":"в марте"},{"text":"в январе"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Разность дней рождения должна быть кратна семи в обычные и високосные годы."},{"title":"Решение","text":"Между январём и апрелем в високосный год появляется 29 февраля. Разность увеличивается на день, поэтому не может оставаться кратной семи."},{"title":"Ответ","text":"Во всех остальных предложенных месяцах даты лежат после 29 февраля. Например, к 1 апреля подходят 6 мая, 3 июня, 5 августа и 25 марта при разностях в целое число недель."}]},{"number":13,"title":"Куб с разрезанной гранью","question":"Бумажный кубик разрезан по некоторым рёбрам, и одна из граней разрезана по диагоналям. Какие из следующих развёрток не могли получиться?","options":[{"text":"1 и 3"},{"text":"1 и 5"},{"text":"3 и 4"},{"text":"3 и 5"},{"text":"2 и 4"}],"condition":{"src":"assets/grades-7-8/2008/task-13.svg","width":546,"height":345,"alt":"Куб с разрезанной гранью и пять пронумерованных развёрток"},"answer":3,"points":4,"review":[{"title":"Решение","text":"Четыре треугольника должны сложиться в одну отсутствующую грань, а пять целых квадратов — в остальные грани."},{"title":"Решение","text":"В развёртке 3 треугольники над верхним и под нижним квадратами попадают на ту же грань, что и крайний левый квадрат. В развёртке 5 верхний треугольник также попадает на уже занятую боковую грань."},{"title":"Ответ","text":"В 1, 2 и 4 треугольники смыкаются четырьмя частями одной свободной грани без нахлёста. Не подходят 3 и 5."}]},{"number":14,"title":"Остановки автобуса","question":"В начале маршрута в автобус сели 23 человека. Водитель автобуса очень спешил, а поэтому останавливался только тогда, когда хотели выйти более четверти людей, едущих в автобусе. Заходить вообще никогда никто не успевал. Какое наибольшее число раз мог останавливаться этот автобус?","options":[{"text":"6"},{"text":"7"},{"text":"8"},{"text":"9"},{"text":"23"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Чтобы продлить маршрут, на каждой остановке выпускаем наименьшее целое число пассажиров, строго большее четверти. При большем остатке можно сделать не меньше дальнейших остановок: максимум остатка после каждого шага растёт вместе с числом пассажиров."},{"title":"Ответ","text":"Первоначальные 23 пассажира убывают до 17, 12, 8, 5, 3, 2, 1 и 0. Автобус остановится 8 раз."}]},{"number":15,"title":"Биссектриса равна основанию","question":"В равнобедренном треугольнике ABC биссектриса CD угла при основании равна основанию AC. Чему равен угол CDB?","options":[{"text":"90°"},{"text":"100°"},{"text":"108°"},{"text":"120°"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-7-8/2008/task-15.svg","width":240,"height":264,"alt":"Треугольник ABC с основанием AC и биссектрисой CD"},"answer":2,"points":4,"review":[{"title":"Решение","text":"Пусть ∠ACD = x. Тогда ∠ACB = ∠CAB = 2x. Из AC = CD следует, что ∠CDA = ∠CAD = 2x."},{"title":"Ответ","text":"В треугольнике ACD сумма углов даёт 2x + x + 2x = 180°, откуда x = 36°. Смежный с ∠CDA угол CDB равен 180° − 72° = 108°."}]},{"number":16,"title":"Произведение процентов","question":"40% от числа 2 умножили на 60% от числа 2. Что получилось?","options":[{"text":"2400% от числа 2"},{"text":"24% от числа 2"},{"text":"50% от числа 2"},{"text":"48% от числа 2"},{"text":"240% от числа 2"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"40% от 2 равно 0,8, а 60% от 2 равно 1,2. Их произведение равно 0,96."},{"title":"Ответ","text":"Сравниваем результат с числом 2: 0,96 : 2 = 0,48, то есть 48%."}]},{"number":17,"title":"Разности цифр","question":"Для каждого двузначного числа из цифры десятков вычли цифру единиц и все получившиеся результаты сложили. Чему равна сумма?","options":[{"text":"90"},{"text":"100"},{"text":"55"},{"text":"45"},{"text":"0"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Каждая цифра десятков от 1 до 9 встречается десять раз, а каждая цифра единиц от 0 до 9 — девять раз."},{"title":"Ответ","text":"Суммы цифр в обоих разрядах равны 45 до учёта повторений. Разность равна 10 · 45 − 9 · 45 = 45."}]},{"number":18,"title":"Углы равнобедренного","question":"Джон считает, что всякий равнобедренный треугольник является остроугольным. Какой из следующих треугольников показывает, что Джон не прав?","options":[{"text":"60°, 80°, 40°","image":"assets/grades-7-8/2008/task-18-answer-1.svg","description":"Треугольник с углами 60°, 80° и 40°"},{"text":"80°, 50°, 50°","image":"assets/grades-7-8/2008/task-18-answer-2.svg","description":"Треугольник с углами 80°, 50° и 50°"},{"text":"40°, 120°, 20°","image":"assets/grades-7-8/2008/task-18-answer-3.svg","description":"Треугольник с углами 40°, 120° и 20°"},{"text":"30°, 30°, 120°","image":"assets/grades-7-8/2008/task-18-answer-4.svg","description":"Треугольник с углами 30°, 30° и 120°"},{"text":"60°, 60°, 60°","image":"assets/grades-7-8/2008/task-18-answer-5.svg","description":"Треугольник с тремя углами 60°"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Для опровержения нужен треугольник с двумя равными углами, у которого один угол не острый."},{"title":"Ответ","text":"У Г два равных угла по 30° и тупой угол 120°. У В тоже есть 120°, но углы 40° и 20° различны."}]},{"number":19,"title":"Одинаковые букеты роз","question":"У флориста (составителя букетов) имеются розы: 42 красные, 24 белые и 36 жёлтых. Какое наибольшее количество одинаковых букетов он может составить, если хочет использовать все имеющиеся розы?","options":[{"text":"4"},{"text":"6"},{"text":"8"},{"text":"10"},{"text":"12"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Количество букетов должно делить все три числа 42, 24 и 36. Наибольший общий делитель 42 и 24 равен 6, а 36 тоже делится на 6."},{"title":"Ответ","text":"Получаем 6 букетов по 7 красных, 4 белых и 6 жёлтых роз в каждом."}]},{"number":20,"title":"Фонтан и башенные часы","question":"Фонтан на площади старинного города связан с часами на башне: он работает, когда хотя бы одна из стрелок часов находится между цифрами 3 и 4 или между цифрами 8 и 9. Сколько времени в течение суток этот фонтан не работает?","options":[{"text":"16 ч 40 мин"},{"text":"14 ч 30 мин"},{"text":"12 ч 20 мин"},{"text":"20 ч 10 мин"},{"text":"22 ч 45 мин"}],"condition":{"src":"assets/grades-7-8/2008/task-20.svg","width":237,"height":243,"alt":"Циферблат с закрашенными секторами от 3 до 4 и от 8 до 9"},"answer":0,"points":4,"review":[{"title":"Решение","text":"Минутная стрелка находится в заданных секторах 10 минут каждый час, всего 120 минут за 12 часов. Часовая стрелка проходит каждый из двух секторов за час, всего тоже 120 минут."},{"title":"Решение","text":"Дважды за 12 часов, пока часовая стрелка идёт по нужному сектору, минутная проводит 10 минут в нужных секторах. Значит, 20 минут были посчитаны дважды."},{"title":"Ответ","text":"Фонтан работает 120 + 120 − 20 = 220 минут за 12 часов. Не работает за сутки 2 · (720 − 220) = 1000 минут, или 16 ч 40 мин."}]},{"number":21,"title":"Год рождения де Моргана","question":"Шотландскому математику Августу де Моргану в году с номером n² исполнилось n лет. Он умер в 1871 году. В каком году он родился?","options":[{"text":"1806"},{"text":"1848"},{"text":"1849"},{"text":"1828"},{"text":"1799"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Год рождения равен n² − n = n(n − 1). Квадрат 44² = 1936 лежит после 1871 года, поэтому n ≤ 43."},{"title":"Ответ","text":"При n = 43 год рождения 43 · 42 = 1806. При n ≤ 42 получаем не позднее 42 · 41 = 1722, а среди предложенных вариантов таких лет нет."}]},{"number":22,"title":"Девочки в походе","question":"В поход пошло несколько учеников школы. Девочек среди участников похода оказалось больше 45%, но меньше 50%. Какое наименьшее количество девочек могло быть в походе?","options":[{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Если девочек d, то мальчиков хотя бы d + 1, иначе доля девочек достигнет 50%. При d ≤ 4 максимальная доля получается у 4 девочек из 9 и равна примерно 44,4%."},{"title":"Ответ","text":"Пять девочек из 11 участников дают долю 5/11, то есть примерно 45,45%. Она лежит между 45% и 50%."}]},{"number":23,"title":"Угол в квадрате с дугой","question":"ABCD — квадрат, точки M и N — середины сторон BC и AD. Окружность радиуса AB с центром в точке A пересекает отрезок MN в точке P. Чему равен угол APC?","options":[{"text":"120°"},{"text":"135°"},{"text":"150°"},{"text":"165°"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-7-8/2008/task-23.svg","width":249,"height":243,"alt":"Квадрат ABCD, середины M и N и точка пересечения P с окружностью"},"answer":1,"points":5,"review":[{"title":"Решение","text":"В прямоугольном треугольнике ANP катет AN равен половине гипотенузы AP, поэтому ∠APN = 30°. Так как AB ∥ PN, то ∠PAB = 30°."},{"title":"Решение","text":"В треугольнике ABP стороны AP и AB равны, поэтому ∠APB = ∠ABP = (180° − 30°) : 2 = 75°. По параллельности PM и AB угол BPM тоже равен 75°."},{"title":"Ответ","text":"Точки B и C симметричны относительно MN, поэтому ∠MPC = 75°. Угол от PA до PC через луч PB равен 75° + 75° + 75° = 225°, а меньший угол APC равен 135°."}]},{"number":24,"title":"Дистанция двух машин","question":"Две машины едут по асфальтированной дороге со скоростью 80 км/ч, сохраняя дистанцию 24 метра. Когда машина сворачивает на грунтовую дорогу, её скорость резко падает до 50 км/ч. Каким будет расстояние между машинами на грунтовой дороге?","options":[{"text":"10 м"},{"text":"15 м"},{"text":"18 м"},{"text":"24 м"},{"text":"32 м"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Когда первая машина уже свернула, второй ещё нужно проехать 24 м до поворота со скоростью 80 км/ч."},{"title":"Ответ","text":"За это же время первая проедет по грунту со скоростью 50 км/ч расстояние 24 · 50 : 80 = 15 м. Затем скорости сравняются, и дистанция останется равной 15 м."}]},{"number":25,"title":"Расстояния между точками","question":"На прямой отметили n точек. Среди попарных расстояний между этими точками встречаются 1 см, 2 см, 3 см, 4 см, 5 см, 6 см, 7 см, 8 см и 9 см. Каково наименьшее из возможных значений n?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Четыре точки дают только 4 · 3 : 2 = 6 пар, а нам нужны хотя бы 9 пар с разными расстояниями."},{"title":"Ответ","text":"Возьмём точки с координатами 0, 1, 2, 6, 9. От 0 получаем 1, 2, 6, 9, от 1 — ещё 5 и 8, от 2 — 4 и 7, а между 6 и 9 расстояние 3. Значит, пяти точек достаточно."}]},{"number":26,"title":"Имя мальчика","question":"Один странный мальчик по средам и пятницам говорит только правду, по вторникам всегда лжёт, а в остальные дни недели он может и солгать, и сказать правду. Семь дней подряд мальчика спрашивали, как его зовут. Первые шесть ответов, по порядку, были таковы: Женя, Боря, Вася, Вася, Петя, Боря. Как он ответил на седьмой день?","options":[{"text":"Петя"},{"text":"Боря"},{"text":"Женя"},{"text":"Вася"},{"text":"невозможно определить"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Ответы за среду и пятницу должны совпасть. В первых шести ответах нет одинаковых имён, произнесённых с разницей два дня или пять дней в обратном направлении. Значит, седьмой день — среда или пятница."},{"title":"Решение","text":"Если седьмой день — среда, то вторым была пятница, а шестым вторник. В оба дня сказано «Боря», хотя в один день он говорит правду, а в другой лжёт."},{"title":"Ответ","text":"Значит, седьмой день — пятница. В среду, которая была пятым днём, он назвался Петей. В пятницу он тоже назовётся Петей."}]},{"number":27,"title":"Ребус KAN − GAR","question":"В числовом ребусе KAN − GAR = OO разным буквам соответствуют разные цифры, одинаковым — одинаковые. Найдите A, если известно, что число KAN — самое большое из возможных.","options":[{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"},{"text":"9"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Десятки отменяются. Значит, 100(K − G) + N − R — положительное двузначное число с одинаковыми цифрами. Разность N − R лежит от −9 до 9, поэтому K − G = 1, а результат лежит между 91 и 99."},{"title":"Решение","text":"Из таких чисел подходит только 99, значит, O = 9. Поэтому K не может быть 9. Попробуем K = 8, тогда G = 7, а наибольшая доступная цифра для A — 6."},{"title":"Ответ","text":"Пример 864 − 765 = 99 доказывает, что A = 6 достигается при наибольших возможных первых двух цифрах KAN."}]},{"number":28,"title":"Произведение до n","question":"Чему равно n, если 1 · 2 · 3 · … · n = 2¹⁵ · 3⁶ · 5³ · 7² · 11 · 13?","options":[{"text":"12"},{"text":"13"},{"text":"14"},{"text":"15"},{"text":"16"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"В 16! показатели простых равны 8 + 4 + 2 + 1 = 15 для 2, 5 + 1 = 6 для 3, а для 5, 7, 11, 13 — соответственно 3, 2, 1, 1."},{"title":"Ответ","text":"Это все простые до 16, значит, разложение совпало. Произведение от 1 до n строго растёт при n ≥ 2, так что n = 16."}]},{"number":29,"title":"Биссектрисы четырёхугольника","question":"Отметим все точки пересечения прямых, на которых лежат биссектрисы выпуклого четырёхугольника. Какое наибольшее число отмеченных точек может оказаться вне четырёхугольника?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Равномерно сдвигаем четыре стороны внутрь, сохраняя их параллельность. Пока все стороны существуют, их пересечения движутся по четырём исходным биссектрисам, поскольку равноудалены от соответствующих сторон."},{"title":"Решение","text":"В общем положении одна сторона сжимается в точку внутри исходной фигуры. Там встретились две исходные биссектрисы. Две оставшиеся вершины нового треугольника продолжают идти по двум другим исходным биссектрисам, и они встречаются в центре его вписанной окружности. В предельных случаях две пары также пересекаются внутри, хотя точки могут совпасть. Из шести пар не больше четырёх могут встретиться снаружи."},{"title":"Ответ","text":"Четыре внешние точки получаются, например, у четырёхугольника A(0, 7), B(2, 5), C(5, 4), D(1, 7). Биссектрисы A и D, B и C встречаются внутри, а пары AB, AC, BD и CD — снаружи."}]},{"number":30,"title":"Завтрак Пятачка и Пуха","question":"Пятачок съедает горшочек мёда за 10 минут, миску малины — за 13 минут и выпивает банку сгущённого молока за 14 минут. Винни-Пух съедает горшочек мёда за 6 минут, миску малины — тоже за 6 минут и выпивает банку сгущённого молока за 7 минут. За какое наименьшее время Винни-Пух и Пятачок могут управиться с завтраком, состоящим из горшочка мёда, миски малины и банки сгущённого молока?","options":[{"text":"11 мин"},{"text":"12 мин"},{"text":"12 1/19 мин"},{"text":"13 мин"},{"text":"14 мин"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"За 12 минут Пятачок съест мёд и выпьет 2/14 молока. Пух съест малину и выпьет 6/7 молока. Доли молока 2/14 + 6/7 дают целую банку."},{"title":"Решение","text":"Один Пух затратил бы 19 минут. Каждая минута труда Пятачка экономит Пуху 6/10 минуты на мёде, 6/13 на малине и 7/14 на молоке."},{"title":"Ответ","text":"За T минут Пятачок экономит не больше T/2 + 1 минуты Пуха: на малине и молоке экономия не превышает половины, а на мёде за срок до 10 минут можно добавить не больше одной минуты. Для завершения нужно T + T/2 + 1 ≥ 19, откуда T ≥ 12."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2008-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2008] ?? []).find(edition => edition.id === "2008-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
